package app.unifeed.cache;
import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*; import org.junit.jupiter.api.Test; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.data.redis.core.ValueOperations;
class PasswordResetStoreTest {@Test void consumesAndDeletesResetCode(){StringRedisTemplate redis=mock(StringRedisTemplate.class);@SuppressWarnings("unchecked")ValueOperations<String,String> values=mock(ValueOperations.class);when(redis.opsForValue()).thenReturn(values);when(values.get("password-reset:user@university.edu")).thenReturn("123456");PasswordResetStore store=new PasswordResetStore(redis);assertThat(store.consume("user@university.edu")).isEqualTo("123456");verify(redis).delete("password-reset:user@university.edu");}}
